public static int longestStableRun(int[] readings) {
    int longest = 0, length = 0, previous = 0;
    for (int value : readings) {
        if (value < 0 || value > 100) {
            length = 0;
        } else {
            length = length > 0 && Math.abs(value - previous) <= 3 ? length + 1 : 1;
            longest = Math.max(longest, length);
        }
        previous = value;
    }
    return longest;
}
