public static int longestStableRun(int[] readings) {
    int i = 0, current = 0, answer = 0;
    while (i < readings.length) {
        if (readings[i] < 0 || readings[i] > 100) {
            current = 0;
        } else {
            if (current == 0 || Math.abs(readings[i] - readings[i - 1]) > 3) current = 1;
            else current++;
            if (current > answer) answer = current;
        }
        i++;
    }
    return answer;
}

