private static boolean validReading(int x) {
    return x >= 0 && x <= 100;
}
public static int longestStableRun(int[] readings) {
    int current = 0, maximum = 0;
    for (int i = 0; i < readings.length; i++) {
        if (!validReading(readings[i])) current = 0;
        else if (i > 0 && validReading(readings[i - 1]) && Math.abs(readings[i] - readings[i - 1]) <= 3) current++;
        else current = 1;
        maximum = Math.max(maximum, current);
    }
    return maximum;
}
