public static int longestStableRun(int[] readings) {
    int best = 0, streak = 0, last = 0;
    for (int x : readings) {
        if (x < 0 || x > 100) streak = 0;
        else {
            int delta = x - last;
            if (streak == 0 || delta < -3 || delta > 3) streak = 1;
            else ++streak;
            best = Math.max(best, streak);
        }
        last = x;
    }
    return best;
}
