public static int longestStableRun(int[] readings) {
    int[] endingHere = new int[readings.length];
    int result = 0;
    for (int i = 0; i < readings.length; i++) {
        if (readings[i] >= 0 && readings[i] <= 100) {
            endingHere[i] = i > 0 && endingHere[i - 1] > 0 && Math.abs(readings[i] - readings[i - 1]) <= 3
                ? endingHere[i - 1] + 1 : 1;
        }
        result = Math.max(result, endingHere[i]);
    }
    return result;
}

// Initialise current length and maximum length to zero.
// Visit each index of readings, without changing or filtering the array.
// Outside the inclusive 0..100 range: current length becomes zero.
// Otherwise, if current length is positive and the absolute difference
// from the immediately preceding reading is at most three, increment it.
// For every other valid reading, current length becomes one.
// After each index, maximum length becomes max(maximum length, current length).
// Return maximum length when the traversal is finished.

