public static int longestStableRun(int[] readings) {
    int answer = 0, i = 0;
    while (i < readings.length) {
        if (readings[i] < 0 || readings[i] > 100) { i++; continue; }
        int beginning = i++;
        while (i < readings.length && readings[i] >= 0 && readings[i] <= 100
                && Math.abs(readings[i] - readings[i - 1]) <= 3) i++;
        answer = Math.max(answer, i - beginning);
    }
    return answer;
}
